import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    """
    Extract numeric values from a JSON structure at the specified key path
    and return a matplotlib Figure containing a boxplot.

    Raises:
        ValueError: If JSON data is empty/corrupted, key_path is invalid,
                    or no numeric data is found.
        KeyError: If a specified key is missing or the path cannot be traversed.
    """
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data is empty or invalid.")

    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError("JSON data is corrupted or invalid.") from e

    if key_path is None:
        key_path = []
    elif not isinstance(key_path, list):
        raise ValueError("key_path must be a list of keys.")

    current = data
    for key in key_path:
        if not isinstance(current, dict):
            raise KeyError(f"Cannot traverse key '{key}' through a non-dict object.")
        if key not in current:
            raise KeyError(f"Key '{key}' not found.")
        current = current[key]

    def collect_numeric(obj):
        values = []

        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(collect_numeric(v))
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                values.extend(collect_numeric(item))
        else:
            if isinstance(obj, (bool, np.bool_)):
                return values
            if isinstance(obj, (int, float, np.integer, np.floating)):
                val = float(obj)
                if np.isfinite(val):
                    values.append(val)

        return values

    values = collect_numeric(current)

    if not values:
        raise ValueError("No numeric data found at the specified path.")

    fig, ax = plt.subplots(figsize=(6, 4))
    ax.boxplot(values, vert=True, patch_artist=True)
    ax.set_title("Boxplot of Extracted Numeric Data")
    ax.set_ylabel("Value")
    ax.set_xticks([1])
    ax.set_xticklabels(["Data"])
    plt.tight_layout()
    return fig
